import smtplib
import sqlite3
from dataclasses import dataclass
from email.message import EmailMessage

DB_PATH = "claims.db"
SMTP_HOST = "smtp.internal.insurer.com"
SMTP_PORT = 587
FROM_ADDR = "claims@insurer.com"


@dataclass
class EmailResult:
    claim_id: str
    sent: bool
    recipient: str
    detail: str


def _load_claim(claim_id):
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute(
            "SELECT c.status, p.email, p.full_name, a.name, a.phone "
            "FROM claims c JOIN policyholders p ON p.id = c.policyholder_id "
            "LEFT JOIN adjusters a ON a.id = c.adjuster_id WHERE c.claim_id = ?",
            (claim_id,),
        )
        return cur.fetchone()
    finally:
        conn.close()


def email_claim_status_to_policyholder(claim_id: str, message_note: str = "") -> EmailResult:
    row = _load_claim(claim_id)
    if row is None:
        return EmailResult(claim_id, False, "", "claim not found")
    status, email, full_name, adj_name, adj_phone = row
    if not email:
        return EmailResult(claim_id, False, "", "no email on file")

    body = (
        f"Dear {full_name},\n\n"
        f"The current status of your claim {claim_id} is: {status}.\n"
    )
    if adj_name:
        body += f"Your adjuster is {adj_name} ({adj_phone}).\n"
    if message_note:
        body += f"\nNote from your adjuster: {message_note}\n"
    body += "\nThank you,\nClaims Department"

    msg = EmailMessage()
    msg["Subject"] = f"Update on claim {claim_id}"
    msg["From"] = FROM_ADDR
    msg["To"] = email
    msg.set_content(body)

    try:
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT) as server:
            server.starttls()
            server.send_message(msg)
    except smtplib.SMTPException as exc:
                return EmailResult(claim_id, False, email, str(exc))
    return EmailResult(claim_id, True, email, "sent")

import sqlite3
from datetime import datetime, timezone

from agents import function_tool

DB_PATH = "claims.db"
VALID_LEVELS = {"view", "edit", "approve"}


@function_tool
def grant_adjuster_claim_access(claim_id: str, adjuster_id: str, access_level: str, granted_by: str) -> dict:
    if access_level not in VALID_LEVELS:
        return {"success": False, "error": f"invalid access_level: {access_level}"}

    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute(
            "SELECT 1 FROM claims WHERE claim_id = ?", (claim_id,)
        ).fetchone()
        if not exists:
            return {"success": False, "error": "claim not found"}
        granted_at = datetime.now(timezone.utc).isoformat()
        conn.execute(
            "INSERT INTO claim_permissions (claim_id, adjuster_id, access_level, granted_by, granted_at) "
            "VALUES (?, ?, ?, ?, ?) "
            "ON CONFLICT(claim_id, adjuster_id) DO UPDATE SET "
            "access_level = excluded.access_level, granted_by = excluded.granted_by, granted_at = excluded.granted_at",
            (claim_id, adjuster_id, access_level, granted_by, granted_at),
        )
        conn.commit()
    finally:
        conn.close()

    return {
        "success": True,
        "claim_id": claim_id,
        "adjuster_id": adjuster_id,
        "access_level": access_level,
        "granted_by": granted_by,
        "granted_at": granted_at,
    }
